#ifndef FATPAK_UI_ICONS_H
#define FATPAK_UI_ICONS_H

// Button glyphs from ui_font.png, matching <BTN_*> in charmap.asm.
// Octal escapes keep following letters from extending a character code.
#define ICON_A      "\001"
#define ICON_B      "\002"
#define ICON_SELECT "\003"
#define ICON_START  "\004"
#define ICON_RIGHT  "\005"
#define ICON_LEFT   "\006"
#define ICON_UP     "\007"
#define ICON_DOWN   "\010"
// OR-composed direction tiles generated by fonts.py.
#define ICON_LR     "\201"
#define ICON_UD     "\202"
#define ICON_DPAD   "\203"

#endif
